function query() {
  return `WITH customer_totals AS (
    SELECT c.id, c.name, c.country, SUM(o.amount_cents) AS total
    FROM customers AS c
    JOIN orders AS o ON o.customer_id = c.id
    WHERE o.status = 'paid'
    GROUP BY c.id, c.name, c.country
  ),
  ranked AS (
    SELECT country, name, total,
           ROW_NUMBER() OVER (
             PARTITION BY country
             ORDER BY total DESC, id
           ) AS rank
    FROM customer_totals
  )
  SELECT country, name, total
  FROM ranked
  WHERE rank = 1
  ORDER BY country`;
}
